package cn.minidayz.patcher;
import java.io.*;import java.nio.*;import java.security.*;import java.security.cert.*;import java.security.spec.*;import java.util.*;import java.util.zip.*;
public final class Signing {
 public static final String CERT_SHA="21fa47120af53f71b39e886eaf0d71a159c34a2d332646a1cf0820a59549ad10";
 public static final class Identity{public PrivateKey key;public X509Certificate cert;public String fingerprint;}
 // A small Base64 decoder keeps this signing engine usable both on Android and JVM tests.
 static byte[] b64(String s)throws IOException{String chars="ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";ByteArrayOutputStream o=new ByteArrayOutputStream();int v=0,bits=0;for(char c:s.toCharArray()){if(c=='=' )break;int d=chars.indexOf(c);if(d<0){if(Character.isWhitespace(c))continue;throw new IOException("E_KEY_FORMAT");}v=(v<<6)|d;bits+=6;if(bits>=8){bits-=8;o.write((v>>bits)&255);}}return o.toByteArray();}
 static byte[] pem(String text,String name)throws IOException{String start="-----BEGIN "+name+"-----",end="-----END "+name+"-----";int a=text.indexOf(start),b=text.indexOf(end,a);FilesEx.require(a>=0&&b>a,"E_KEY_FORMAT: 需要未加密 PKCS8 私钥及 X.509 证书的组合 PEM");return b64(text.substring(a+start.length(),b));}
 public static Identity identity(byte[] pem)throws Exception{String text=new String(pem,"UTF-8");Identity x=new Identity();x.key=KeyFactory.getInstance("RSA").generatePrivate(new PKCS8EncodedKeySpec(pem(text,"PRIVATE KEY")));x.cert=(X509Certificate)CertificateFactory.getInstance("X.509").generateCertificate(new ByteArrayInputStream(pem(text,"CERTIFICATE")));x.fingerprint=FilesEx.hex(MessageDigest.getInstance("SHA-256").digest(x.cert.getEncoded()));Signature s=Signature.getInstance("SHA256withRSA");byte[] challenge="MDZ-local-key-check".getBytes("UTF-8");s.initSign(x.key);s.update(challenge);byte[] signed=s.sign();s.initVerify(x.cert);s.update(challenge);FilesEx.require(s.verify(signed),"E_KEY_PAIR: 私钥与证书不匹配");return x;}
 public static byte[] keyFromFile(File file)throws Exception{byte[] head=new byte[4];FileInputStream in=new FileInputStream(file);int n=in.read(head);in.close();if(n==4&&head[0]=='P'&&head[1]=='K'){ZipFile z=new ZipFile(file);try{Map<String,ZipEntry> entries=FilesEx.entries(z);byte[] found=null;for(ZipEntry e:entries.values())if(e.getName().toLowerCase(Locale.US).endsWith(".pem")&&e.getSize()<262144){byte[] b=FilesEx.read(z.getInputStream(e),262144);try{Identity x=identity(b);if(x.fingerprint.equals(CERT_SHA)){FilesEx.require(found==null,"E_KEY_AMBIGUOUS: 多个匹配签名文件");found=b;}}catch(java.security.GeneralSecurityException bad){}catch(IOException bad){if(bad.getMessage().startsWith("E_KEY_AMBIGUOUS"))throw bad;}}FilesEx.require(found!=null,"E_KEY_MISSING: ZIP 中未找到匹配的组合 PEM");return found;}finally{z.close();}}return FilesEx.read(new FileInputStream(file),262144);}
 static byte[] u32(long n){return ByteBuffer.allocate(4).order(ByteOrder.LITTLE_ENDIAN).putInt((int)n).array();}static byte[] u64(long n){return ByteBuffer.allocate(8).order(ByteOrder.LITTLE_ENDIAN).putLong(n).array();}
 static byte[] concat(byte[]... a)throws IOException{ByteArrayOutputStream o=new ByteArrayOutputStream();for(byte[] b:a)o.write(b);return o.toByteArray();}static byte[] lp(byte[] b)throws IOException{return concat(u32(b.length),b);}
 static long uint(byte[] b,int at){return ByteBuffer.wrap(b,at,4).order(ByteOrder.LITTLE_ENDIAN).getInt()&0xffffffffL;}
 static final class ZipEnd{long eocd,cd,size;byte[] tail;}
 static ZipEnd end(RandomAccessFile r)throws Exception{long len=r.length();FilesEx.require(len>=22&&len<0xffffffffL,"E_APK_SIZE");int n=(int)Math.min(len,65557);byte[] b=new byte[n];r.seek(len-n);r.readFully(b);for(int i=n-22;i>=0;i--)if(uint(b,i)==0x06054b50L&&i+22+((b[i+20]&255)|((b[i+21]&255)<<8))==n){FilesEx.require(b[i+4]==0&&b[i+5]==0&&b[i+6]==0&&b[i+7]==0,"E_ZIP_MULTIDISK");ZipEnd z=new ZipEnd();z.eocd=len-n+i;z.cd=uint(b,i+16);z.size=uint(b,i+12);FilesEx.require(z.cd+z.size==z.eocd&&z.cd<z.eocd,"E_ZIP_DIRECTORY");z.tail=Arrays.copyOfRange(b,i,n);return z;}throw new IOException("E_ZIP_EOCD");}
 static byte[] contentDigest(RandomAccessFile r,long before,long cd,long eocd,byte[] tail,FilesEx.Watch w)throws Exception{MessageDigest all=MessageDigest.getInstance("SHA-256");long count=(before+1048575)/1048576+(eocd-cd+1048575)/1048576+(tail.length+1048575)/1048576;all.update((byte)0x5a);all.update(u32(count));for(long[] section:new long[][]{{0,before},{cd,eocd-cd}}){r.seek(section[0]);long left=section[1];while(left>0){FilesEx.check(w);int n=(int)Math.min(1048576,left);byte[] b=new byte[n];r.readFully(b);MessageDigest d=MessageDigest.getInstance("SHA-256");d.update((byte)0xa5);d.update(u32(n));d.update(b);all.update(d.digest());left-=n;}}for(int p=0;p<tail.length;p+=1048576){int n=Math.min(1048576,tail.length-p);MessageDigest d=MessageDigest.getInstance("SHA-256");d.update((byte)0xa5);d.update(u32(n));d.update(tail,p,n);all.update(d.digest());}return all.digest();}
 public static void sign(File unsigned,File signed,Identity id,FilesEx.Watch w)throws Exception{RandomAccessFile r=new RandomAccessFile(unsigned,"r");try{ZipEnd z=end(r);byte[] digest=contentDigest(r,z.cd,z.cd,z.eocd,z.tail,w);int alg=0x0103;byte[] data=concat(lp(lp(concat(u32(alg),lp(digest)))),lp(lp(id.cert.getEncoded())),lp(new byte[0]));Signature signer=Signature.getInstance("SHA256withRSA");signer.initSign(id.key);signer.update(data);byte[] sig=signer.sign();byte[] record=concat(lp(data),lp(lp(concat(u32(alg),lp(sig)))),lp(id.cert.getPublicKey().getEncoded()));byte[] value=lp(lp(record));byte[] pair=concat(u64(4+value.length),u32(0x7109871aL),value);long size=pair.length+24;byte[] block=concat(u64(size),pair,u64(size),"APK Sig Block 42".getBytes("US-ASCII"));byte[] tail=z.tail.clone();System.arraycopy(u32(z.cd+block.length),0,tail,16,4);FileOutputStream out=new FileOutputStream(signed);try{r.seek(0);FilesEx.slice(r,out,z.cd,w);out.write(block);r.seek(z.cd);FilesEx.slice(r,out,z.eocd-z.cd,w);out.write(tail);out.getFD().sync();}finally{out.close();}}finally{r.close();}}
 static byte[] take(ByteBuffer b)throws IOException{FilesEx.require(b.remaining()>=4,"E_SIGNATURE_FORMAT");int n=b.getInt();FilesEx.require(n>=0&&n<=b.remaining(),"E_SIGNATURE_FORMAT");byte[] v=new byte[n];b.get(v);return v;}static ByteBuffer le(byte[] b){return ByteBuffer.wrap(b).order(ByteOrder.LITTLE_ENDIAN);}
 public static String verify(File file,String expected,FilesEx.Watch w)throws Exception{RandomAccessFile r=new RandomAccessFile(file,"r");try{ZipEnd z=end(r);r.seek(z.cd-24);byte[] footer=new byte[24];r.readFully(footer);FilesEx.require(new String(footer,8,16,"US-ASCII").equals("APK Sig Block 42"),"E_SIGNATURE_MISSING");long size=le(footer).getLong();FilesEx.require(size>=24&&size<1048576&&size+8<z.cd,"E_SIGNATURE_SIZE");long start=z.cd-size-8;r.seek(start);byte[] raw=new byte[(int)size+8];r.readFully(raw);ByteBuffer block=le(raw);FilesEx.require(block.getLong()==size,"E_SIGNATURE_SIZE");long pair=block.getLong();FilesEx.require(pair==size-32&&block.getInt()==0x7109871a,"E_SIGNATURE_SCHEME");byte[] value=new byte[(int)pair-4];block.get(value);ByteBuffer signers=le(take(le(value)));ByteBuffer signer=le(take(signers));byte[] data=take(signer);ByteBuffer sigs=le(take(signer));byte[] pub=take(signer);ByteBuffer sig=le(take(sigs));FilesEx.require(sig.getInt()==0x103,"E_SIGNATURE_ALGORITHM");byte[] signature=take(sig);ByteBuffer sd=le(data);ByteBuffer digests=le(take(sd));ByteBuffer certs=le(take(sd));X509Certificate cert=(X509Certificate)CertificateFactory.getInstance("X.509").generateCertificate(new ByteArrayInputStream(take(certs)));String fingerprint=FilesEx.hex(MessageDigest.getInstance("SHA-256").digest(cert.getEncoded()));FilesEx.require(expected.equals(fingerprint)&&Arrays.equals(pub,cert.getPublicKey().getEncoded()),"E_SIGNATURE_IDENTITY");Signature v=Signature.getInstance("SHA256withRSA");v.initVerify(cert);v.update(data);FilesEx.require(v.verify(signature),"E_SIGNATURE_INVALID");ByteBuffer d=le(take(digests));FilesEx.require(d.getInt()==0x103,"E_DIGEST_ALGORITHM");byte[] original=take(d);byte[] tail=z.tail.clone();System.arraycopy(u32(start),0,tail,16,4);FilesEx.require(Arrays.equals(original,contentDigest(r,start,z.cd,z.eocd,tail,w)),"E_CONTENT_DIGEST");return fingerprint;}finally{r.close();}}
}
